"""Authenticated access to retained USB camera evidence images."""
from __future__ import annotations

import re
from typing import Any

from fastapi import APIRouter, Depends, HTTPException
from fastapi.responses import FileResponse


def create_camera_evidence_router(services: Any) -> APIRouter:
    router = APIRouter()

    @router.get("/api/camera/evidence/{filename}", dependencies=[Depends(services.require_admin_query)])
    def camera_evidence(filename: str) -> FileResponse:
        """Serve only UUID-named JPEG evidence generated by the USB camera."""
        if not re.fullmatch(r"[0-9a-f]{32}\.jpg", filename):
            raise HTTPException(status_code=404, detail="Không tìm thấy ảnh bằng chứng.")
        try:
            path = services.evidence_dir_provider() / filename
            if not path.is_file():
                raise HTTPException(status_code=404, detail="Ảnh bằng chứng không tồn tại hoặc đã bị xóa.")
            return FileResponse(path, media_type="image/jpeg", headers={"Cache-Control": "no-store"})
        except HTTPException:
            raise
        except Exception as exc:  # noqa: BLE001
            services.logger.exception("Không đọc được ảnh bằng chứng camera USB")
            raise HTTPException(status_code=503, detail="Không thể đọc ảnh bằng chứng lúc này.") from exc

    return router
